import{_ as o,o as a,c as t,a2 as c}from"./chunks/framework.x7b91k6X.js";const u=JSON.parse('{"title":"漫画 · 第 3 话 ObjC 运行时：消息机制与转发","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.03-objc-runtime.md","filePath":"comics/EP.03-objc-runtime.md","lastUpdated":1792677465000}'),r={name:"comics/EP.03-objc-runtime.md"};function d(i,e,l,n,s,h){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="漫画-·-第-3-话-objc-运行时-消息机制与转发" tabindex="-1">漫画 · 第 3 话 ObjC 运行时：消息机制与转发 <a class="header-anchor" href="#漫画-·-第-3-话-objc-运行时-消息机制与转发" aria-label="Permalink to &quot;漫画 · 第 3 话 ObjC 运行时：消息机制与转发&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../03-objc-runtime">03-objc-runtime.md</a> ｜ 原画：<a href="./EP.03-objc-runtime.svg">EP.03-objc-runtime.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：写了 <code>[obj performSelector:@selector(foo)]</code>，方法名拼错，App 直接 <code>unrecognized selector</code> 闪退。</li><li><strong>Runtime 长老</strong>：带她看 <code>objc_msgSend</code> 的查找流程和消息转发三步兜底。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>ObjC 的方法调用不是函数调用，而是「给对象发消息」。编译器只负责把 <code>[obj foo]</code> 翻译成 <code>objc_msgSend(obj, @selector(foo))</code>，方法存不存在要到运行时才查。查不到也不会立刻崩——运行时会依次尝试三步消息转发，只有三步都不处理才抛 <code>unrecognized selector</code>。这套机制正是 KVO、关联对象、方法欺骗的底层基础。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p><code>unrecognized selector sent to instance</code> 是 ObjC 最经典的崩溃之一。根源在于 ObjC 的动态性：方法调用在编译期不做存在性检查，selector 只是一个字符串，到运行时才去对象的类上查找方法实现。写错方法名、或者对象实际类型和声明不符，都会触发。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>objc_msgSend</code> 的查找链路：</p><ol><li>先查对象的方法缓存（<code>objc_msgSend</code> 用汇编手写，极快）；</li><li>缓存未命中，查类的方法列表；</li><li>再沿父类链向上查；</li><li>全程没找到，进入<strong>消息转发</strong>。</li></ol><p>消息转发三步：</p><ul><li><strong>第一步 <code>resolveInstanceMethod:</code></strong>：给类一个机会动态添加方法实现（<code>class_addMethod</code>）；</li><li><strong>第二步 <code>forwardingTargetForSelector:</code></strong>：返回另一个对象，让它去响应这个 selector（最轻量）；</li><li><strong>第三步 <code>methodSignatureForSelector:</code> + <code>forwardInvocation:</code></strong>：拿到完整的 <code>NSInvocation</code>，可以任意修改参数、目标，再调用。</li></ul><p>三步全部返回默认值或 nil，才会走到 <code>doesNotRecognizeSelector:</code> 抛异常。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><ul><li>想让某个未知 selector 不崩，最轻量的做法是重写 <code>forwardingTargetForSelector:</code> 返回备用对象；</li><li>想实现「动态属性」「自动 NSCoding」这类黑魔法，用 <code>resolveInstanceMethod:</code> + <code>class_addMethod</code> 在运行时补方法；</li><li>KVO 的本质就是 Runtime 在运行时动态子类化，重写 setter 插入 <code>willChangeValueForKey:</code> / <code>didChangeValueForKey:</code>。</li></ul><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>ObjC 方法调用即发消息，编译期不检查，运行时才查方法列表。</li><li>找不到方法走三步转发：动态添加→转对象→完整 Invocation。</li><li>KVO、关联对象、方法欺骗全靠 Runtime API，混编时读懂它们不踩坑。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么给 <code>nil</code> 发消息在 ObjC 里不会崩溃，而 Swift 强制解包 nil 会？</p><p><strong>答</strong>：ObjC 的 <code>objc_msgSend</code> 第一行就判断 <code>if (obj == nil) return;</code>，给 nil 发消息直接返回 0/NULL/nil，不做任何查找。这是 ObjC 的语言设计。而 Swift 的 <code>!</code> 强制解包在运行时会检查 Optional 是否为 <code>.none</code>，是 nil 就主动触发 <code>fatalError</code>。两者的「空」哲学完全不同：ObjC 宽容静默，Swift 明确失败。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>查看 <code>examples/Sources/ObjCUtils/ObjCUtils.m</code> 中的 nullability 注解与方法声明，再阅读第 3 章关于 <code>class_addMethod</code> 和 <code>method_exchangeImplementations</code> 的示例，在 Xcode 里新建一个 ObjC 类实验消息转发第二步。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>Runtime 黑魔法看完了，可新写的 Swift 代码要跟老 ObjC 类互相调用，桥接头怎么配、<code>@objc</code> 怎么加？第 4 话《混编：桥接头与渐进迁移》，打通双语言壁垒。</p>',26)])])}const m=o(r,[["render",d]]);export{u as __pageData,m as default};
